import{_ as e,o as a,c as d,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"练习：为未知 CLI 写屏幕证据规则","description":"","frontmatter":{},"headers":[],"relativePath":"pebrel-course/exercises.md","filePath":"pebrel-course/docs/exercises.md"}'),o={name:"pebrel-course/exercises.md"};function i(l,t,c,h,n,s){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="练习-为未知-cli-写屏幕证据规则" tabindex="-1">练习：为未知 CLI 写屏幕证据规则 <a class="header-anchor" href="#练习-为未知-cli-写屏幕证据规则" aria-label="Permalink to &quot;练习：为未知 CLI 写屏幕证据规则&quot;">​</a></h1><p>练习顺序沿验证依赖排列：每题需要的每项能力都已在正文示范过。做题前先回看对应章节的演练槽，再独立完成；全部练习只需锁定 clone 与纸笔，不需要安装或构建目标仓库。</p><h2 id="练习-1-给-gemini-cli-写一条含负向证据的-idle-规则" tabindex="-1">练习 1：给 Gemini CLI 写一条含负向证据的 idle 规则 <a class="header-anchor" href="#练习-1-给-gemini-cli-写一条含负向证据的-idle-规则" aria-label="Permalink to &quot;练习 1：给 Gemini CLI 写一条含负向证据的 idle 规则&quot;">​</a></h2><p>回看<a href="./10-screen-evidence.html">第 10 章</a>的演练与 gemini.toml 一节：真实仓库的选择是「无 idle 规则、不凭提示符伪造空闲」。你的任务是推翻它——假设新版 Gemini CLI 的空闲画面底部固定有一行 <code>» </code> 输入框提示，且回合进行中会出现 <code>· Working</code> 角标。写出你的 TOML 规则：区域选哪个、正向条件是什么、负向证据（not）挡什么、优先级定多少、与 working 规则的相对次序怎么排。写完后回答：如果 <code>· Working</code> 角标偶发闪现半秒，你的规则会误判吗——这正是真实仓库选择不写规则的理由。</p><h2 id="练习-2-单句柄吞吐上限的变体演算" tabindex="-1">练习 2：单句柄吞吐上限的变体演算 <a class="header-anchor" href="#练习-2-单句柄吞吐上限的变体演算" aria-label="Permalink to &quot;练习 2：单句柄吞吐上限的变体演算&quot;">​</a></h2><p>回看<a href="./07-sftp-engine.html">第 7 章</a>的封顶公式（分块 ÷ RTT）。对下面两条链路各算出单句柄上限与填满管道所需句柄数，并判断是否撞上窗口 64：</p><table tabindex="0"><thead><tr><th>链路</th><th>RTT</th><th>带宽</th></tr></thead><tbody><tr><td>跨城专线</td><td>30 ms</td><td>200 Mbps</td></tr><tr><td>卫星链路</td><td>600 ms</td><td>50 Mbps</td></tr></tbody></table><p>算完后用一句话解释：为什么卫星链路的结论会让「多句柄分段」从优化变成必需。（对照口径：分块 32 KiB，按十进制带宽换算，填满需向上取整。）</p><h2 id="练习-3-为-git-分支设计一个补全源" tabindex="-1">练习 3：为 git 分支设计一个补全源 <a class="header-anchor" href="#练习-3-为-git-分支设计一个补全源" aria-label="Permalink to &quot;练习 3：为 git 分支设计一个补全源&quot;">​</a></h2><p>回看<a href="./15-completion-engine.html">第 15 章</a>的 Completer trait 接缝。写出 <code>GitBranchCompleter</code> 的 <code>fetch</code> 签名与返回值类型，回答三个问题：候选从哪里来（提示：你不需要在 trait 里执行 git 命令——静态列表源的构造器形态是什么）；返回的 <code>Vec&lt;SemanticSuggestion&gt;</code> 里每项装什么；这个类型为什么天然不依赖任何终端视图。最后指出：匹配与排序发生在你实现的代码里，还是 CandidateMatcher 里——「源只产候选」的分工线画在哪。</p><h2 id="练习-4-摘叶预言" tabindex="-1">练习 4：摘叶预言 <a class="header-anchor" href="#练习-4-摘叶预言" aria-label="Permalink to &quot;练习 4：摘叶预言&quot;">​</a></h2><p>回看<a href="./04-split-tree.html">第 4 章</a>的树叶集合不变式与<a href="./05-gpui-shell.html">第 5 章</a>的 close_pane 链。画一棵三叶树：根为 LeftRight 分割，左侧是叶子 1，右侧是 TopBottom 分割（上叶 2、下叶 3）。依次执行 <code>remove_leaf(2)</code>、<code>remove_leaf(1)</code>，每步写出：树的形状、<code>leaves()</code> 的返回、<code>RemoveOutcome</code> 的变体、focused 移交给谁。如果第二步删的是不存在的 99 呢？</p><h2 id="练习-5-恢复护栏推演" tabindex="-1">练习 5：恢复护栏推演 <a class="header-anchor" href="#练习-5-恢复护栏推演" aria-label="Permalink to &quot;练习 5：恢复护栏推演&quot;">​</a></h2><p>回看<a href="./11-session-persistence.html">第 11 章</a>的四步次序（load → should_restore → quarantine → mark_boot_attempt）与「先落盘计数」的次序合同。对下表每种初始状态，写出下一次启动的裁定（恢复 / 放弃恢复）与裁定后盘上的 boot_attempts 值：</p><table tabindex="0"><thead><tr><th>初始盘上 boot_attempts</th><th>tabs</th><th>上次启动存活？</th></tr></thead><tbody><tr><td>0</td><td>非空</td><td>是</td></tr><tr><td>1</td><td>非空</td><td>否</td></tr><tr><td>2</td><td>非空</td><td>否</td></tr><tr><td>3</td><td>非空</td><td>否</td></tr><tr><td>0</td><td>空</td><td>—</td></tr></tbody></table><p>再回答：为什么 mark_boot_attempt 必须「先落盘再恢复」——把两步换序，表里哪一行会变成死循环？</p><h2 id="练习-6-毕业任务-三问判断" tabindex="-1">练习 6（毕业任务）：三问判断 <a class="header-anchor" href="#练习-6-毕业任务-三问判断" aria-label="Permalink to &quot;练习 6（毕业任务）：三问判断&quot;">​</a></h2><p>回看<a href="./16-review.html">第 16 章</a>的三个跨子系统场景。现在轮到你：一个 issue 要求「在终端里按 <code>Ctrl+Alt+P</code> 时，把当前 pane 里 AI 的最后一条回答导出为 Markdown 文件」。写出落点 crate、会碰到的禁区（所有权地图的 must-not-become）、影响面（哪几章建立的积木会被调用：回答捕获、文档 tab 模型、还是别的），以及你会在哪个探针上先加断言。</p>',18)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
